    {
      "resource": "vllm.qwen35.fa-prefill-schedule",
      "scope": "vllm-process",
      "mode": "exclusive"
    },
    {
      "resource": "vllm.qwen35.gdn-prefill-schedule",
      "scope": "vllm-process",
      "mode": "exclusive"
    }
  ],
  "components": [
    {
      "component_id": "vllm-hust-prefill-microflow",
      "contracts": [
        "vllm.general-plugin.experimental"
      ],
      "execution_planes": [
        "worker"
      ],
      "isolation": "trusted_in_process",
      "implementation_ref": "hust_prefill_microflow:register",
      "permissions": []
    }
  ],
  "activation": {
    "entry_points": [
      {
        "group": "vllm.general_plugins",
        "name": "hust_prefill_microflow"
      }
    ],
    "environment": {
      "HUST_PREFILL_MICROFLOW_ENABLED": "1",
