"""Explicit experimental control; verify mode is deliberately intrusive.

Only builder instance methods are replaced. Off mode restores native dispatch.
No cross-step metadata cache or source-file patch is installed.
"""

from __future__ import annotations

import hashlib
import importlib
import inspect
from dataclasses import is_dataclass
from pathlib import Path
from types import MethodType

from tools.gdn_prepare_fastpath import try_build

_STATE = "_hybrid_gdn_prepare_candidate"
SOURCE_PINS = {
    "vllm_ascend.ops.gdn_attn_builder": (
        "42cc0284b57193112b8a8ad19704aa3401f02294f0c36333c307d748f462fe16"
    ),
    "vllm.v1.attention.backends.gdn_attn": (
        "27f5561c4b191f2be5a4a91820a6c64a38b755477b3f037178fb02bbc3bc1caf"
    ),
    "vllm.v1.attention.backends.utils": (
        "f4f2f106ad84aa77cdf0b09d6948878f4e74c56568309312ec47bd190cc710cd"
    ),
}


def check_source(module, expected):
    path = Path(module.__file__)
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    if digest != expected:
        raise ValueError(f"native source differs: {module.__file__}")
    return {"path": str(path), "sha256": digest}


def compare_metadata(expected, actual, torch, path="metadata"):
    """Compare every dataclass/dynamic field, including device tensor contents."""
    if isinstance(expected, torch.Tensor):
        if (
            not isinstance(actual, torch.Tensor)
            or expected.dtype != actual.dtype
            or expected.shape != actual.shape
            or expected.device != actual.device
            or not torch.equal(expected, actual)
        ):
            raise ValueError("native metadata mismatch: " + path)
    elif is_dataclass(expected):
        if type(expected) is not type(actual) or vars(expected).keys() != vars(actual).keys():
            raise ValueError("native metadata fields mismatch: " + path)
        for name, value in vars(expected).items():
            compare_metadata(value, getattr(actual, name), torch, path + "." + name)
    elif type(expected) is not type(actual) or expected != actual:
        raise ValueError("native metadata scalar mismatch: " + path)


def _wrapper(state, entry):
    def build(
        builder,
        common_prefix_len,
        common_attn_metadata,
        num_accepted_tokens=None,
        num_decode_draft_tokens_cpu=None,
        fast_build=False,
    ):
        if state["failed"]:
            raise ValueError("candidate session previously failed")
        args = (
            common_prefix_len,
            common_attn_metadata,
            num_accepted_tokens,
            num_decode_draft_tokens_cpu,
        )
        try:
            candidate = try_build(builder, *args, api=state["api"], fast_build=fast_build)
            if candidate is None:
                entry["fallback"] += 1
                return entry["native"](*args, fast_build=fast_build)
            entry["hits"] += 1
            if state["mode"] == "verify":
                native = entry["native"](*args, fast_build=fast_build)
                compare_metadata(native, candidate, state["api"].torch)
                value = int(candidate.num_accepted_tokens.item())
                key = str(value)
                entry["acceptance"][key] = entry["acceptance"].get(key, 0) + 1
                entry["compared"] += 1
            return candidate
        except BaseException:
            state["failed"] = True
            raise

    return build


def snapshot(worker):
    state = getattr(worker, _STATE, None)
    if state is None:
        return {"rank": worker.rank, "mode": "off", "installed": False}
    return {
        "rank": worker.rank,
        "mode": state["mode"],
        "installed": True,
        "failed": state["failed"],
        "sources": state["sources"],
        "groups": [
            {
                key: entry[key]
                for key in ("gid", "layers", "hits", "fallback", "compared", "acceptance")
            }
            for entry in state["entries"]
        ],
    }


def _validate_pool(worker, receipt_hashes):
    if set(receipt_hashes) != {"0", "1"}:
        raise ValueError("both-rank pool receipt hashes required")
    receipt = worker.inspect_hybrid_pool_adaptation()
    if hashlib.sha256(receipt.encode()).hexdigest() != receipt_hashes[str(worker.rank)]:
        raise ValueError("local pool receipt hash mismatch")
    from tools import eagle_pool_worker

    pool = getattr(worker, eagle_pool_worker._STATE)
    eagle_pool_worker._unchanged(worker, pool)
    eagle_pool_worker._check_allocation(worker, pool)


def _revalidate(worker, receipt_hashes, state):
    _validate_pool(worker, receipt_hashes)
    for entry in state["entries"]:
        if type(entry["builder"]).build is not entry["native"].__func__:
            raise ValueError("native class binding changed after verification")
        if "group" in entry and (
            worker.model_runner.attn_groups[entry["gid"]][entry["attn_gid"]] is not entry["group"]
            or entry["group"].get_metadata_builder(0) is not entry["builder"]
            or list(entry["group"].layer_names) != entry["layers"]
        ):
            raise ValueError("native builder group ownership changed")
    for cls, bindings in state.get("class_bindings", []):
        if any(getattr(cls, name) is not original for name, original in bindings.items()):
            raise ValueError("native builder helper binding changed")
    for name, source in state["sources"].items():
        check_source(importlib.import_module(name), source["sha256"])
    if "helper_bindings" in state:
        for name, original in state["helper_bindings"].items():
            if getattr(state["api"], name) is not original:
                raise ValueError("native helper binding changed after verification")


def _initialize(worker, receipt_hashes):
    _validate_pool(worker, receipt_hashes)
    modules = {name: importlib.import_module(name) for name in SOURCE_PINS}
    sources = {name: check_source(modules[name], sha) for name, sha in SOURCE_PINS.items()}
    api = modules["vllm_ascend.ops.gdn_attn_builder"]
    cls = api.AscendGDNAttentionMetadataBuilder
    for obj in (cls.build, api._build_actual_seq_lengths, api.GDNSpecDecodeMetadata):
        if Path(inspect.getsourcefile(obj)).resolve() != Path(api.__file__).resolve():
            raise ValueError("native builder/helper binding differs from verified source")
    entries = []
    runner = worker.model_runner
    for gid, groups in enumerate(runner.attn_groups):
        for attn_gid, group in enumerate(groups):
            builder = group.get_metadata_builder(0)
            if type(builder) is not cls:
                continue
            if "build" in vars(builder) or builder.build.__func__ is not cls.build:
                raise ValueError("builder has an unknown instance binding")
            if len(group.layer_names) != 1:
                raise ValueError("expected one GDN layer per verified EAGLE group")
            entries.append(
                dict(
                    gid=gid,
                    attn_gid=attn_gid,
                    group=group,
                    layers=list(group.layer_names),
                    builder=builder,
                    native=builder.build,
                    hits=0,
                    fallback=0,
                    compared=0,
                    acceptance={},
                )
            )
    if len(entries) != 30 or len({id(e["builder"]) for e in entries}) != 30:
        raise ValueError("expected 30 distinct verified GDN builders")
    return dict(
        api=api,
        sources=sources,
        entries=entries,
        mode="off",
        failed=False,
        class_bindings=[
            (cls, {name: obj for name, obj in vars(cls).items() if inspect.isfunction(obj)})
        ],
        helper_bindings={
            name: getattr(api, name)
            for name in (
                "_build_actual_seq_lengths",
                "GDNSpecDecodeMetadata",
                "GDNSpecCausalConv1dMetadata",
                "GDNAttentionMetadata",
                "_treat_single_token_prefills_with_state_as_decodes",
                "mamba_get_block_table_tensor",
            )
        },
    )


def configure(worker, mode, receipt_hashes):
    if mode not in ("off", "verify", "on"):
        raise ValueError("unknown candidate mode")
    state = getattr(worker, _STATE, None)
    if mode == "on" and (
        state is None or state["failed"] or any(e["compared"] == 0 for e in state["entries"])
    ):
        raise ValueError("successful per-builder verification required before enablement")
    if state is None:
        if mode == "off":
            return snapshot(worker)
        state = _initialize(worker, receipt_hashes)
        setattr(worker, _STATE, state)
    if state["failed"] and mode != "off":
        raise ValueError("candidate verification previously failed")
    if mode != "off":
        try:
            _revalidate(worker, receipt_hashes, state)
        except BaseException:
            state["failed"] = True
            raise
    # Validate every binding before changing any instance; never overwrite an
    # unrelated patch that arrived after initial verification.
    for entry in state["entries"]:
        if type(entry["builder"]).build is not entry["native"].__func__:
            state["failed"] = True
            raise ValueError("native class binding changed")
        current = vars(entry["builder"]).get("build")
        expected = entry.get("wrapped") if state["mode"] != "off" else None
        if current is not expected:
            raise ValueError("candidate builder binding changed")
    for entry in state["entries"]:
        builder = entry["builder"]
        if "build" in vars(builder):
            del builder.build
        if mode != "off":
            entry["wrapped"] = MethodType(_wrapper(state, entry), builder)
            builder.build = entry["wrapped"]
    state["mode"] = mode
    return snapshot(worker)

